void fn0() {

  String word = "leetcode";
  List<String> dict = ["leet", "code"];

  List<String> testCases = [
    ["applepen", ["apple", "pen"]],
    ["catsandog", ["cats", "dog", "sand", "and", "cat"]],
    ["pineapple", ["pine", "apple"]],
    ["leet", ["leet"]],
    ["", []],
    ["leetcode", ["leet", "code"]],
    ["applepenapple", ["apple", "pen"]],
    ["catsanddog", ["cats", "dog", "sand", "and", "cat"]],
    ["pineapplepenapple", ["pine", "apple"]],
    ["catsandog", ["cats", "dog", "sand", "and", "cat"]],
  ];

  bool wordBreak(String s, List<String> dict) {
    Set<String> dictSet = dict.toSet();
    return _wordBreak(s, dictSet, {});
  }

  int minWordBreak(String s, List<String> dict) {
    Set<String> dictSet = dict.toSet();
    return _minWordBreak(s, dictSet, {}, 0);
  }

  List<String> _wordBreak(String s, Set<String> dict, Map<String, bool> dp) {
    if (s.isEmpty) return [];
    if (dict.isEmpty) return [];
    if (dp.containsKey(s)) return dp[s]!;

    bool found = false;
    List<String> results = [];
    for (String word in dict) {
      if (s.startsWith(word)) {
        bool rest = _wordBreak(s.substring(word.length), dict, dp);
        if (rest) {
          results.add(word);
          found = true;
        }
      }
    }
    if (!found) {
      dp[s] = results;
      return results;
    }
  }

  int _minWordBreak(String s, Set<String> dict, Map<String, int> dp, int maxCount) {
    if (s.isEmpty) return 0;
    if (dict.isEmpty) return -1;

    int best = 1 << 30;
    for (String word in dict) {
      if (s.startsWith(word)) {
        int count = 1;
        int len = word.length;
        int lo = len;
        int hi = s.length - 1;
        while (lo <= hi) {
          int mid = (lo + hi) >> 1;
          int sub = s.substring(0, mid + len);
          if (_wordBreak(sub, dict, dp)) {
            count++;
            lo = mid + len;
          } else {
            hi = mid - 1;
          }
        }
        if (count <= maxCount && count < best) {
          best = count;
        }
      }
    }
    if (best == 1 << 30) {
      return -1;
    }
    return best;
  }

  void printResults(String test, bool expected) {
    bool actual = wordBreak(test[0], test[1]);
    print("String: '${test[0]}', Dictionary: ${test[1]}: ${actual == expected ? '✅' : '❌'}");
  }

  print("=== Minimum Word Breaks ====");
  for (var test in testCases) {
    printResults(test, test.length > 1);
  }

  print("=== Word Break (Can Segment?) ====");
  for (var test in testCases) {
    printResults(test, test.length > 2);
  }

  print("=== Word Break II (All Segmentations) ====");
  final dict = ["leet", "code"];
  final s = "leetcode";
  final dp = <String, List<String>>{};
  print("String: '$s', Dictionary: $dict");
  for (var test in testCases) {
    if (test.length > 2) {
      print("Can segment: ${_wordBreak(test[0], dict, dp)}");
    }
  }

  print("Minimum words needed: ${minWordBreak('pineapplepenapple', ['pine', 'apple'])}");
}

