List<String> wordBreak(String s, List<String> dict) {
  Set<String> dictSet = dict.toSet();
  List<bool> dp = List.filled(s.length + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j]) {
        String sub = s.substring(j, i);
        if (dictSet.contains(sub)) {
          dp[i] = true;
          break;
        }
      }
    }
  }

  List<String> results = [];
  void backtrack(int idx, String current, List<String> remaining) {
    if (idx == s.length) {
      if (current.isEmpty) {
        results.add("");
      } else {
        return;
      }
    }

    for (int j = idx; j < s.length; j++) {
      String sub = s.substring(j, s.length);
      if (dp[j + 1] && !dictSet.contains(sub)) {
        continue;
      }

      String next = current + sub;
      backtrack(j + 1, next, remaining);
    }
  }

  for (int i = 0; i <= s.length; i++) {
    if (dp[i]) {
      backtrack(i, "", s.substring(0, i));
    }
  }
  return results;
}

