  List<bool> dp = List.filled(n + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j]) {
        String sub = s.substring(j, i);
        if (dictionary.contains(sub)) {
          dp[i] = true;
          break;
        }
      }
    }
  }

  return dp[n];
}

