bool wordBreak(String s, List<String> wordDict) {
  int n = s.length;
  List<bool> dp = List.filled(n + 1, false);
  dp[0] = true; 

  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j]) {
        String sub = s.substring(j, i);
        if (wordDict.contains(sub)) {
          dp[i] = true;
          break;
        }
      }
    }
  }
  return dp[n];
}

void allWordBreak(String s, List<String> wordDict, List<String> path, List<String> res) {
  if (s.isEmpty) {
    res.add(path.join(' '));
    return;
  }

  for (int i = 0; i < s.length; i++) {
    String first = s[i];
    if (wordDict.contains(first)) {
      path.add(first);
      allWordBreak(s.substring(i + 1), wordDict, path, res);
      path.removeLast(); 
    }
  }
}

void minWordBreak(String s, List<String> wordDict, int k, List<String> path, int idx) {
  if (idx == s.length) {
    print(path.join(' '));
    return;
  }

  for (int i = idx; i < s.length; i++) {
    String first = s[i];
    if (wordDict.contains(first)) {
      path.add(first);
      minWordBreak(s.substring(i + 1), wordDict, k - 1, path, i + 1);
      path.removeLast(); 
    }
  }
}

