  bool binarySearch(List<String> items, String pattern) {
    List<int> patPos = [];
    for (int i = 0; i < pattern.length; i++) {
      patPos.add(i);
    }
    List<bool> res = List.filled(items.length, false);
    List<int> iter = [];
    int n = pattern.length;
    for (int i = 0; i < items.length; i++) {
      if (items[i].length < n) continue;
      bool ok = true;
      for (int j = 0; j < n; j++) {
        if (items[i][j] != pattern[j]) {
          ok = false;
          break;
        }
      }
      if (!ok) continue;
      iter.clear();
      iter.addAll(patPos);
      int l = 0, r = items[i].length - n;
      while (l < r) {
        int m = (l + r) >> 1;
        bool found = true;
        for (int k = 0; k < n; k++) {
          if (items[i][iter[k] + m] != pattern[k]) {
            found = false;
            break;
          }
        }
        if (found) {
          r = m;
        } else {
          l = m + 1;
        }
      }
      res[i] = l < n;
    }
    return res.join().contains('true');
  }

  List<String> examples = [
    'EXAMPLE',
    'THIS IS A SIMPLE EXAMPLE',
