  List<String> items = [];
  int n = 0;
  bool valid = false;

  for (int i = 0; i < args.length; i++) {
    String arg = args[i];
    switch (i) {
      case 0:
        k = int.tryParse(arg) ?? 0;
        if (k < 0) {
          print('First argument must be an integer k (size of combinations). Got: $k');
          valid = true;
          break;
        }
        if (k >= n) {
          print('k must be between 0 and n (inclusive). n=$n, k=$k');
          valid = true;
          break;
        }
        continue;
      case 1:
        items = arg.split(',');
        for (int j = 0; j < items.length; j++) {
          if (j > 0) items[j] = items[j - 1] + items[j];
        }
        continue;
      case 2:
        n = int.tryParse(arg) ?? 0;
        if (n < 0) {
          print('Second argument must be an integer n (total items). Got: $n');
          valid = true;
          break;
        }
        continue;
      default:
        print('Usage: dart run <file.dart> <k> <item1> <item2> ...');
        valid = true;
        break;
    }

    if (!valid) {
      print('No args provided. Using default input: k=$k, items=$items, n=$n');
      break;
    }

    int total = 1;
    for (int i = 0; i < k; i++) {
      total *= n - i;
      total ~/= (i + 1);
    }
    print('Total combinations: $total');

    List<List<String>> combinations = [];
    List<String> current = [];

    void backtrack(List<String> remaining, int idx) {
      if (current.length == k) {
        combinations.add(List.from(current));
        return;
      }
      if (idx >= remaining.length) return;

      current.add(remaining[idx]);
      backtrack(remaining.sublist(idx + 1), idx + 1);
      current.removeLast();

      backtrack(remaining.sublist(idx + 1), idx);
    }

    backtrack(items, 0);

    for (var combo in combinations) {
      print(combo);
    }
  }
}

