void fn0() {
  final rng = Random(0);

  const int rows = 3;
  const int cols = 4;
  const int base = 15;

  final List<List<int>> grid = List.generate(
    rows,
    (_) => List.generate(cols, (i) => rng.nextInt(base) + 1),
  );

  final List<int> hourIds = List.generate(cols, (i) => i);

  int luminance(List<int> cells) {
    int sum = 0;
    for (final v in cells) {
      sum += v * 0.33;
    }
    return sum.truncate();
  }

  int transitionScore(List<int> prev, List<int> curr) {
    int t = 0;
    for (var i = 0; i < prev.length; i++) {
      if (prev[i] != curr[i]) t++;
    }
    return t;
  }

  int editDistance(List<int> a, List<int> b) {
    final dp = List.generate(a.length + 1, (_) => List.filled(b.length + 1, 0));

    for (var i = 0; i <= a.length; i++) dp[i][0] = i;
    for (var j = 0; j <= b.length; j++) dp[0][j] = j;

    for (var i = 1; i <= a.length; i++) {
      for (var j = 1; j <= b.length; j++) {
        final cost = a[i - 1] == b[j - 1] ? 0 : 1;

        final deletions = dp[i - 1][j] + 1;     
        final insertions = dp[i][j - 1] + 1;    
        final substitutions = dp[i - 1][j - 1] + cost; 

        dp[i][j] = deletions < insertions
            ? (deletions < substitutions ? deletions : substitutions)
            : (insertions < substitutions ? insertions : substitutions);
      }
    }

    return dp[a.length][b.length];
  }

  List<int> hourToCells(int hour) {
    final result = <int>[];
    for (var i = 0; i < grid.length; i++) {
      if (grid[i].contains(hour)) result.add(i);
    }
    return result;
  }

  String cellsToSymbols(List<int> cells) {
    if (cells.isEmpty) return '';
    if (cells.length == 1) return cells[0].toString();

    final mid = cells.length ~/ 2;
    final left = cells.sublist(0, mid);
    final right = cells.sublist(mid);

    final syms = cells.map((c) => c ? '#' : ' ').join().padRight(3);
    final spaces = (3 - syms.length) .padLeft(3);
    final leftSym = cells.sublist(0, mid).map((c) => c ? '#' : ' ').join().padRight(3);
    final rightSym = cells.sublist(mid).map((c) => c ? '#' : ' ').join().padRight(3);

    return '| $spaces$leftSym$spaces|$syms|$rightSym$spaces|';
  }

  void visualize(List<int> cells, String title) {
    final symbols = cells.map((c) => c ? '#' : ' ').join().padRight(3);
    final spaces = (3 - symbols.length) .padLeft(3);
    print(title);
    print('-' * 50);
    for (var i = 0; i < cells.length; i++) {
      if (i % 7 == 6) print('| $spaces${cells[i]} $symbols${cells[i]}');
    }
    print('|${spaces.padRight(3)}|${symbols.padRight(3)}|');
  }

  print('User Activity Heatmap (Day x Hour)');
  print('=' * 50);

  visualize(grid[0], 'Initial grid');

  for (final hour in hourIds) {
    final current = hourToCells(hour);
    final transitions = transitionScore(
      current,
      grid[hour.day][hour.hour],
    );
    final groups = editDistance(current, grid[hour.day][hour.hour]);

    final cells = luminance(current) < 20
        ? current
        : current.expand((c) => hourToCells(grid[c][hour.hour])).toList();

    final symbolStr = cells.map((c) => c ? '#' : ' ').join().padRight(3);
    final title = '$hour: ${symbolStr.padRight(3)}/${groups.padRight(3)}';
    visualize(cells, title);
  }

  print('\nLegend:');
  print('  \".\" = low');
  print('  \"*\" = medium');
  print('  \"#\" = high');
  print('  \" \" = no activity');
}

