        }
        priority[k] = 0;
      }
    }
  }
  if (valid.isEmpty) return <String>[];
  valid.sort();
  for (var s in valid) {
    if (priority[s]! >= 2) {
      high.add(s);
    } else {
      low.add(s);
    }
  }
  return high..addAll(low);
}

