@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<String> fn0(String schedule, int minSize) {
  final result = <String>[];
  if (schedule.isEmpty) return result;

  final classes = <String, List<String>>{};
  final openClasses = <String, List<String>>{};
  final conflicts = <String>[];

  for (var part in schedule.split('|')) {
    if (part.isEmpty) continue;

    final idx = part.indexOf(':');
    if (idx == -1) {
      conflicts.add(part);
      continue;
    }

    final className = part[0];
    final timePart = part.substring(idx + 1);
    final times = timePart.split('-');

    if (times.length != 2) {
      conflicts.add(part);
      continue;
    }

    final start = int.parse(times[0]);
    final end = int.parse(times[1]);
    if (start < 0 || end < 0) {
      conflicts.add(part);
      continue;
    }

    final key = '$className:$start';
    final value = <String>[];

    for (var token in openClasses[key] ?? []) {
      if (token.isEmpty) continue;
      value.add(token);
    }

    value.add(part);
    openClasses[key] = value;

    final reverseKey = '$className:$end';
    final reverseValue = <String>[];

    for (var token in openClasses[reverseKey] ?? []) {
      if (token.isEmpty) continue;
      reverseValue.add(token);
    }

    openClasses[reverseKey] = reverseValue;
  }

  for (var entry in openClasses.entries) {
    final className = entry.key[0];
    final start = int.parse(entry.key.substring(1));
    final value = entry.value;

    if (value.isEmpty) continue;

    final end = start + (value.length - 1);
    final key = '$className:$start';
    final reverseKey = '$className:$end';

    if (!classes.containsKey(key)) {
      classes[key] = <String>[];
    }

    for (var token in value) {
      if (token.isEmpty) continue;
      classes[key]!.add(token);
    }

    if (!classes.containsKey(reverseKey)) {
      classes[reverseKey] = <String>[];
    }

    for (var token in value) {
      if (token.isEmpty) continue;
      classes[reverseKey]!.add(token);
    }
  }

  for (var entry in classes.entries) {
    if (entry.value.length >= minSize) {
      result.add(entry.key);
    }
  }

  return result;
}

