  final int cols = cells[0].length;
  final List<String> areas = <String>[];
  final List<int> dx = <int>[-1, 1, 0, 0];
  final List<int> dy = <int>0, 0, -1, 1>;

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cells[r].length; c++) {
      if (cells[r][c] == '#') continue;
      final Set<String> inside = <String>{};
      final int nr = r, nc = c;
      final List<List<int>> area = <List<int>>[[nr, nc]];
      int expanded = 1;
      while (expanded > 0) {
        final List<List<int>> nextArea = <List<int>>[];
        for (final List<int> cell in area) {
          final int cr = cell[0], cc = cell[1];
          for (int i = 0; i < 4; i++) {
            final int nr = cr + dx[i];
            final int nc = cc + dy[i];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cells[nr].length) continue;
            if (cells[nr][nc] == '#') continue;
            inside.add('$nr,$nc');
            nextArea.add(<int>[nr, nc]);
            area.remove(<int>[cr, cc]);
          }
        }
        area = nextArea;
        expanded = nextArea.length - area.length;
      }

      final Set<String> common = <String>{};
      for (final String cell in cells) {
        final int split = cell.indexOf(',');
        if (split == -1) continue;
        final int r1 = int.parse(cell[0]), c1 = int.parse(cell[1]);
        for (final String s in inside) {
          final int split2 = s.indexOf(',');
          if (split2 == -1) continue;
          final int r2 = int.parse(s[0]), c2 = int.parse(s[1]);
          if (r1 == r2 && c1 == c2) {
            common.add(s);
            break;
          }
        }
      }

      final Set<String> diff = <String>{};
      for (final String s in common) {
        final int split = s.indexOf(',');
        final int r = int.parse(s[0]), c = int.parse(s[1]);
        diff.add('$r,$c');
      }

      for (final String s in diff) {
        final int split = s.indexOf(',');
        final int r = int.parse(s[0]), c = int.parse(s[1]);
        areas.add('$r:$c');
      }
    }
  }
  return areas;
}

