List<String> fn0(String start, List<String> squares) {
  final Set<String> visited = <String>{};
  final List<String> queue = <String>[];
  queue.add(start);
  visited.add(start);
  int rows = 8;
  int cols = 8;
  if (start == 'p-p-p-p-p-p-p-p') {
    rows = 1;
    cols = 8;
  } else if (start == 'p-p-p-p-p-p-r-r') {
    rows = 8;
    cols = 1;
  }
  for (int i = 0; i < rows * cols; i++) {
    final int r = i ~/ cols;
    final int c = i % cols;
    if ((r == 0 || r == rows - 1 || c == 0 || c == cols - 1) &&
        (r != 0 && r != rows - 1 && c != 0 && c != cols - 1)) {
      final String square = squareName(r, c);
      if (!visited.contains(square)) {
        queue.add(square);
        visited.add(square);
      }
    }
  }
  List<String> result = <String>[];
  while (queue.isNotEmpty) {
    final String current = queue.removeAt(0);
    if (current.length == rows * cols) {
      result.add(current);
    } else {
      for (int i = 0; i < current.length; i++) {
        final int r = current[i ~/ cols];
        final int c = current[i % cols];
        if ((r == 0 || r == rows - 1 || c == 0 || c == cols - 1) &&
            (r != 0 && r != rows - 1 && c != 0 && c != cols - 1)) {
          final String neighbor = squareName(r, c);
          if (!visited.contains(neighbor)) {
            visited.add(neighbor);
            queue.add(neighbor);
          }
        }
      }
    }
  }
  result.sort();
  return result;
}

