void solveNQueens(int n, [int? current]) {

  if (current == null || current.length != n) {
    for (int i = 0; i < n; i++) {
      List<bool> queenPos = List.filled(n, false);
      queenPos[i] = true;

      bool safe = true;
      for (int j = 0; j < i; j++) {
        int diff = (i - j).abs();
        if (queenPos[j] && queenPos[i] && diff == 0) {
          safe = false;
          break;
        }
        int row = queenPos[j] ? j : -1;
        int col = queenPos[i] ? i : -1;
        if (row == col || row + col == n - 1) {
          safe = false;
          break;
        }
      }
      if (safe) {

        String prettyPrint(List<bool> board) {
          const t = 'Q';
          const e = '.';
          String result = '';
          for (int i = 0; i < board.length; i++) {
            result += board[i] ? t : e;
          }
          return result;
        }

        print('Solution $solution:');
        print(prettyPrint(queenPos));
        print('');
        solution++;
      }
    }
    return;
  }

  List<bool> queenPos = List.filled(n, false);
  for (int i = 0; i < current.length; i++) {
    queenPos[current[i]] = true;
  }

  bool safe = true;
  for (int i = 0; i < n; i++) {
    if (queenPos[i]) {
      for (int j = 0; j < i; j++) {
        int diff = (i - j).abs();
        if (queenPos[j] && queenPos[i] && diff == 0) {
          safe = false;
          break;
        }
        int row = queenPos[j] ? j : -1;
        int col = queenPos[i] ? i : -1;
        if (row == col || row + col == n - 1) {
          safe = false;
          break;
        }
      }
    }
  }
  if (safe) {
    solveNQueens(n, current + [n]);
  }
}

