@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {


  print('Solving N-Queens for N=');
  int n;
  if (args.length != 1) {
    n = 8; 
  } else {
    final nStr = args[0];
    final nVal = int.tryParse(nStr);
    if (nVal == null || nVal < 0) {
      print('Invalid input: $nStr');
      print('Usage: dart run script.dart <N>');
      return;
    }
    n = nVal;
  }

  final board = List.generate(n, (_) => List.filled(n, 0));

  int solutions = 0;
  bool isSafe(int row, int col) {

    for (int r = 0; r < row; r++) {
      final c = board[r][col];
      if (c == 1) return false; 
    }

    int r = row - 1;
    int c = col - 1;
    while (r >= 0 && c >= 0) {
      final qr = board[r][c];
      if (qr == 1) return false;
      r--;
      c--;
    }

    r = row - 1;
    c = col + 1;
    while (r >= 0 && c < n) {
      final qr = board[r][c];
      if (qr == 1) return false;
      r--;
      c++;
    }

    return true;
  }

  void place(int row) {
    if (row == n) {
      solutions++;
      print('Solution $solutions:');
      for (int r = 0; r < n; r++) {
        final line = List.generate(n, (c) => board[r][c] == 1 ? 'Q ' : '.').join(' ');
        print(line);
      }
      print('');
      return;
    }

    for (int col = 0; col < n; col++) {
      if (isSafe(row, col)) {
        board[row][col] = 1;
        place(row + 1);
        board[row][col] = 0; 
      }
    }
  }

  place(0);
  print('Total solutions: $solutions');
}

