Map<String, int> fn0(List<int> arrivalTimes, int holdDuration) {
  if (arrivalTimes.isEmpty) {
    return {'pairCount': 0, 'mashupDuration': 0};
  }

  int n = arrivalTimes.length;
  List<int> dp = List.filled(n, 0);
  int maxPair = 0;
  int bestStart = 0;

  for (int i = 0; i < n; i++) {
    dp[i] = 1;
    for (int j = 0; j < i; j++) {
      if (arrivalTimes[i] - arrivalTimes[j] <= holdDuration) {
        int subPair = dp[j] + 1;
        if (subPair > dp[i]) dp[i] = subPair;
        if (subPair > maxPair) {
          maxPair = subPair;
          bestStart = j;
        }
      }
    }
  }

  int mashupDuration = 0;
  for (int i = bestStart; i < n; i++) {
    mashupDuration += arrivalTimes[i] - arrivalTimes[i - bestStart] - holdDuration;
  }

  return {'pairCount': maxPair, 'mashupDuration': mashupDuration};
}

