Map<String, int> fn0(List<int> beatTicks, int minPairDuration) {
  int n = beatTicks.length;
  if (n == 0) return {'pairCount': 0, 'mashupDuration': 0};

  int maxMashupDuration = 0;
  int currentMashupDuration = 0;

  int left = 0;
  int right = 0;

  while (right < n) {
    while (right < n && beatTicks[right] - beatTicks[left] > minPairDuration) {
      left = right;
    }
    right++;

    if (left > 0) {
      currentMashupDuration = right - left;
      if (currentMashupDuration > maxMashupDuration) {
        maxMashupDuration = currentMashupDuration;
      }
    }
  }

  int pairCount = 0;
  left = 0;
  right = 0;

  while (right < n) {
    while (right < n && beatTicks[right] - beatTicks[left] <= minPairDuration) {
      left = right;
    }
    right++;

    if (left < right) {
      pairCount++;
    }
  }

  return {'pairCount': pairCount, 'mashupDuration': maxMashupDuration};
}

