Map<String, int> fn0(List<int> songIDs, List<int> startTimes, List<int> endTimes) {
  int n = songIDs.length;
  if (n == 0) return {'pairCount': 0, 'mashupDuration': 0};
  List<int> durations = List.filled(n, 0);
  for (int i = 0; i < n; i++) {
    int d = endTimes[i] - startTimes[i];
    if (d < 0) continue;
    if (i > 0 && songIDs[i] == songIDs[i - 1]) {
      int gap = startTimes[i] - endTimes[i - 1];
      if (gap > 0) {
        d = d - gap;
        if (d < 0) d = 0;
      } else {
        d = d + gap;
      }
    }
    durations[i] = d;
  }
  int pairCount = 0;
  int mashupDuration = 0;
  List<int> prefix = List.filled(n + 1, 0);
  for (int i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + durations[i];
  }
  void backtrack(int idx, int currentSum, int currentPair) {
    if (idx == n) {
      pairCount += currentPair;
      mashupDuration += currentSum;
      return;
    }
    if (idx > 0 && songIDs[idx] == songIDs[idx - 1]) {
      int merged = prefix[idx] - prefix[idx - 1];
      backtrack(idx + 1, currentSum + merged, currentPair + 1);
    } else {
      backtrack(idx + 1, currentSum, currentPair);
    }
  }
  backtrack(0, 0, 0);
  return {'pairCount': pairCount, 'mashupDuration': mashupDuration};
}

