Map<String, int> fn0(List<int> songIDs, List<int> startTimes, List<int> endTimes, int minMashupDuration) {
  int n = songIDs.length;
  if (n == 0 || minMashupDuration <= 0) return {'pairCount': 0, 'mashupDuration': 0};
  List<int> parent = List.filled(n, -1);
  List<int> depth = List.filled(n, 0);
  List<int> subtreeSize = List.filled(n, 0);
  int root = 0;

  void dfs(int v, int p) {
    subtreeSize[v] = 1;
    for (int i = 0; i < n; i++) {
      if (songIDs[i] == songIDs[v] && startTimes[i] <= endTimes[v]) {
        parent[i] = v;
        dfs(i, v);
        subtreeSize[v] += subtreeSize[i];
      }
    }
  }

  for (int i = 0; i < n; i++) {
    if (parent[i] == -1) {
      root = i;
    }
  }

  void decompose(int v, int p, int d) {
    depth[v] = d;
    dfs(v, p);
  }

  decompose(root, -1, 0);

  int maxDepth = 0;
  for (int i = 0; i < n; i++) {
    if (depth[i] > maxDepth) maxDepth = depth[i];
  }

  List<int> mergeTimes = List.filled(maxDepth + 1, 0);
  int mergeIdx = 0;

  void query(int v, int p) {
    mergeTimes[depth[v]] += endTimes[v] - startTimes[v];
    for (int i = 0; i < n; i++) {
      if (songIDs[i] == songIDs[v] && startTimes[i] <= endTimes[v]) {
        if (parent[i] != p) {
          query(i, v);
        }
      }
    }
  }

  query(root, -1);

  int pairs = 0;
  for (int t = 0; t < maxDepth + 1; t++) {
    if (mergeTimes[t] > 0) {
      pairs += mergeTimes[t] * (mergeTimes[t] - 1) ~/ 2;
    }
  }

  return {'pairCount': pairs, 'mashupDuration': mergeTimes[maxDepth]};
}

