  int iPairIndex = 0;
  for (int i = 0; i < n; i++) {
    int j = i;
    while (j < n &&
        songIDs[indices[j]] == songIDs[indices[i]] &&
        startTimes[indices[j]] <= endTimes[indices[i]]) {
      j++;
    }
    uniqueCount += j - i;
    currentMashupDuration += endTimes[indices[i]] - startTimes[indices[i]];
    if (i < j - 1) {
      iPairIndex++;
    }
  }
  return {'pairCount': uniqueCount, 'mashupDuration': currentMashupDuration};
}

