class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.unit() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.random() : this(
      rand() * 2 - 1, rand() * 2 - 1, rand() * 2 - 1, rand() * 2 - 1);

  const Quaternion.fromList(List<double> list)
      : this(list[0], list[1], list[2], list[3]);

  const Quaternion.identity() : this(1.0, 1.0, 1.0, 1.0);

  const Quaternion.look(Vector3 axis, double angle) {
    final double s = sin(angle / 2);
    final double c = cos(angle / 2);

    final double x = axis.x * s;
    final double y = axis.y * s;
    final double z = axis.z * s;

    final double w = c;

    return Quaternion(x, y, z, w);
  }

  Quaternion operator +(Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(Quaternion other) =>
      Quaternion(
          x * other.w - y * other.z,
          y * other.w + x * other.z,
          z * other.w - x * other.y,
          w * other.w);

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  double norm() => sqrt(x * x + y * y + z * z + w * w);

  Quaternion normalized() {
    final double n = norm();
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion inverse() => conjugate() / norm();

  Quaternion operator *(double s) => Quaternion(sx, sy, sz, sw);

  @override
  String toString() => 'Quaternion($x, $y, $z, $w)';
}

