  const Quaternion.random() : this(
      math.Random(0).nextDouble() * 2 - 1,
      math.Random(0).nextDouble() * 2 - 1,
      math.Random(0).nextDouble() * 2 - 1,
      math.Random(0).nextDouble() * 2 - 1);

  const Quaternion.fromAxisAngle(
      [double x, double y, double z], double angle) {
    final double sx = x * math.sin(angle / 2);
    final double sy = y * math.sin(angle / 2);
    final double sz = z * math.sin(angle / 2);
    final double sw = math.cos(angle / 2);
    return Quaternion(sx, sy, sz, sw);
  }

  const Quaternion.fromConjugate(Quaternion other)
      : this(other.x, other.y, other.z, other.w);

  const Quaternion.fromNormalized(Quaternion other)
      : this(other.x * other.w,
          other.y * other.w,
          other.z * other.w,
          other.w * other.w);

  const Quaternion.fromAxisAngleAndPoint(
      [double x, double y, double z],
      Point3D point,
      double angle) {
    final Quaternion axisAngle = Quaternion.fromAxisAngle(x, y, z, angle);
    return Quaternion.fromConjugate(axisAngle * Point3D.fromPoint(point));
  }

  const Quaternion.fromBasisVectors() {
    final Quaternion v1 = Quaternion.unit();
    final Quaternion v2 = Quaternion.random();
    final Quaternion v3 = Quaternion.random();
    return v1 * v2 * v3;
  }

  double get realPart => x + y + z + w;

  double get imaginaryPart => x * y + x * z + x * w + y * z + y * w;

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  Quaternion inverse() =>
      Quaternion(x, y, z, 1 / (x * x + y * y + z * z + w * w));

  Quaternion normalized() {
    final double norm = math.sqrt(x * x + y * y + z * z + w * w);
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  Quaternion rotatePoint(Point3D point) =>
      Quaternion.fromAxisAngleAndPoint([x, y, z], point.toPoint(), 90);

  @override
  String toString() => 'Quaternion($x, $y, $z, $w)';

  const Quaternion operator +(const Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  const Quaternion operator -(const Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  const Quaternion operator *(const Quaternion other) =>
      Quaternion(
          x * other.w - y * other.z - z * other.y + w * other.x,
          y * other.w + x * other.z - z * other.x + w * other.y,
          z * other.w + x * other.y - y * other.x + w * z,
          w * other.w);

  const Quaternion operator *(double scalar) =>
      Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  const Quaternion operator /(double scalar) =>
      Quaternion(x / scalar, y / scalar, z / scalar, w / scalar);

  const Quaternion operator ^(int exponent) =>
      Quaternion.fromAxisAngle([x, y, z], exponent * math.pi / 2);
}

