  Point3D rotateAboutZ(double angle) {
    final Quaternion axisAngle = Quaternion.fromAxisAngle([0, 0, 1], angle);
    return Quaternion.fromConjugate(axisAngle * *this);
  }

  Point3D scale(double factor) => Point3D(x * factor, y * factor, z * factor);

  const Point3D operator +(const Point3D other) => Point3D(x + other.x, y + other.y, z + other.z);

