  const Point3D operator /(double scalar) => Point3D(x / scalar, y / scalar, z / scalar);

  const Point3D operator ^(int exponent) => Point3D(x ^ exponent, y ^ exponent, z ^ exponent);

  double get distanceSq => (x - 0) * (x - 0) + (y - 0) * (y - 0) + (z - 0) * (z - 0);

  double get distance => math.sqrt(distanceSq);

