class Quaternion {
  final double x, y, z, w;
  Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.zero() : this(0, 0, 0, 0);
  const Quaternion.unit() : this(1, 0, 0, 1);
  const Quaternion.fromAxisAngle(double ax, double ay, double az, double angle) {
    final double sinA = sin(angle);
    final double cosA = cos(angle);
    return Quaternion(ax * sinA, ay * sinA, az * sinA, cosA);
  }

  const Quaternion.fromBasis(Quaternion v1, Quaternion v2, Quaternion v3) {
    return Quaternion(
      v1.x * v2.y - v1.y * v2.x,
      v1.y * v2.z - v1.z * v2.y,
      v1.z * v2.x - v1.x * v2.z,
      v1.w * v2.w,
    );
  }

  const Quaternion.fromConjugate(Quaternion q) : this(q.x, q.y, q.z, -q.w);

  const Quaternion.fromNormalized(Quaternion q) : this(q.x / q.norm(), q.y / q.norm(), q.z / q.norm(), q.w / q.norm());

  const Quaternion.random() {
    final double r = randomDouble(0, 1);
    final double i = randomDouble(0, 1);
    final double j = randomDouble(0, 1);
    final double k = randomDouble(0, 1);
    return Quaternion(2 * r * i, 2 * r * j, 2 * r * k, sqrt(1 - 8 * r * r));
  }

  Quaternion operator +(Quaternion other) => Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  Quaternion operator -(Quaternion other) => Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  Quaternion operator *(double scalar) => Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  Quaternion operator *(Quaternion other) {
    final double x = other.x * w - x * other.w;
    final double y = other.y * w - y * other.w;
    final double z = other.z * w - z * other.w;
    return Quaternion(x, y, z, x * other.w + y * other.z + z * other.x);
  }
  Quaternion conjugate() => Quaternion(x, y, z, -w);
  double norm() => sqrt(x * x + y * y + z * z + w * w);
  Quaternion inverse() => conjugate() * (1 / norm());

  @override
  String toString() => 'Quaternion($x, $y, $z, $w)';
}

