  var next = <int>[];
  for (var i = 0; i < seeds.length; i++) {
    var s = seeds[i];
    if (s < 0) continue;
    var score = 0;
    var prev = 0;
    for (var r = 0; r < rounds; r++) {
      var die = (r % 2 == 0) ? s + 1 : s - 1;
      if (die < 0) die = 0;
      var bonus = (r % 3 == 0) ? die : 0;
      var total = s + die + bonus;
      if (total > prev) {
        score += total - prev;
        if (score > 0) next.add(score);
      } else {
        score -= prev - total;
        if (score < 0) next.add(0);
      }
      prev = total;
    }
  }
  return next;
}

