    search(x - 1, y, d - 1);
    search(x + 1, y, d - 1);
    search(x, y - 1, d - 1);
    search(x, y + 1, d - 1);
  }

  search(gaugeX, gaugeY, maxDistance);

  if (count == 0) {
    return 0.0;
  }

  return sum / count;
}

