    final List<String> row = maze[i].split('');
    for (int j = 0; j < width; j++) {
      if (row[j] == '#') {
        dp[i][j] = -1;
      } else if (j > 0 && row[j] == row[j - 1]) {
        dp[i][j] = dp[i][j - 1] + 1;
      } else {
        dp[i][j] = 1;
      }
    }
  }

  final Map<String, int> result = {};
  int maxLen = 0;
  int bestStart = -1;
  for (int i = 0; i < n; i++) {
    int curStart = 0;
    int curLen = 0;
    bool canCont = true;
    for (int j = 0; j < width; j++) {
      if (dp[i][j] >= 0) {
        curLen++;
        if (curLen > maxLen) {
          maxLen = curLen;
          bestStart = i;
        }
      } else {
        canCont = false;
        break;
      }
    }
    if (!canCont) {
      break;
    }
  }

  if (bestStart == -1) {
    return {};
  }

  final List<String> rect = [];
  int top = bestStart;
