int lpsArray(String pattern) {
  int n = pattern.length;
  if (n == 0) return 0;
  List<int> dp = List<int>.filled(n, 1);
  int length = 0; 
  int i = 1;

  while (i < n) {
    if (pattern[i] == pattern[length]) {
      length++;
      dp[i] = length;
      i++;
    } else {
      if (length != 0) {
        length = dp[length - 1];
      } else {
        dp[i] = 0;
        i++;
      }
    }
  }
  return dp[n - 1];
}

