    int n = pattern.length;
    int i = 0;
    int len = 0;

    while (i < n - 1) {
      if (pattern[i] == pattern[n - 1 - i]) {
        len++;
        i++;
      } else {
        break;
      }
    }

    return len;
  }

  void computeLPSArray(String pattern, int m, List<List<bool>> lps) {
    int len = lengthOfLongestPrefixSuffix(pattern);

    lps[0][0] = true;
    for (int i = 1; i < m; i++) {
      lps[i][0] = lps[i - 1][0] && (pattern[i] == pattern[i - 1]);
    }

    for (int i = 1; i < m; i++) {
      for (int j = 1; j < n; j++) {
        if (pattern[i - 1] == pattern[j - 1]) {
          lps[j][i] = lps[j - 1][i - 1];
        } else if (pattern[j - 1] != pattern[i - 1]) {
          if (lps[j - 1][i - 1]) {
            lps[j][i] = true;
          }
        }
      }
    }
  }

  void kmpSearch(String text, String pattern) {
    int n = text.length;
    int m = pattern.length;

    if (m == 0 || n == 0) {
