Map<String, int> fn0(List<List<double>> moistureGrid, double refRow, double refCol, double threshold) {
  final moistureMap = <String, double>{};
  final moistureCount = <String, int>{};
  final rows = refRow - threshold;
  final cols = refCol - threshold;
  for (int r = 0; r < moistureGrid.length; r++) {
    for (int c = 0; c < moistureGrid[r].length; c++) {
      if (r >= rows && r <= refRow + threshold && c >= cols && c <= refCol + threshold) {
        moistureMap[r.toStringAsFixed(1)] = moistureGrid[r][c];
      }
    }
  }
  double getMoisture(double row, double col) {
    if (moistureMap.containsKey(row.toStringAsFixed(1))) {
      return moistureMap[row.toStringAsFixed(1)]!;
    } else {
      int ceilRow = ((row + 0.5).ceil() * 4).floor();
    int ceilCol = ((col + 0.5).ceil() * 4).floor();
    double moisture = 0.0;
    int hits = 0;
    for (int r = 0; r < moistureGrid.length; r++) {
      for (int c = 0; c < moistureGrid[r].length; c++) {
        if (r >= ceilRow && r <= ceilRow + threshold && c >= ceilCol && c <= ceilCol + threshold) {
          moisture += moistureGrid[r][c];
          hits++;
        }
      }
    }
    if (hits > 0) {
      return moisture / hits;
    } else {
      return -1.0;
    }
  }
  int getCount(double value) {
    int low = 0;
    int high = moistureGrid.length * moistureGrid[0].length;
    while (low < high) {
      int mid = (low + high) >> 1;
      if (getMoisture(mid / 4.0, mid % 4.0) < value) {
        low = mid + 1;
      } else {
        high = mid;
      }
    }
    return low;
  }
  for (double moisture in moistureMap.values) {
    if (moisture >= threshold) {
      moistureCount[moisture.toStringAsFixed(2)] = (moistureCount[moisture.toStringAsFixed(2)] ?? 0) + 1;
    }
  }
  return moistureCount;
}

