  for (int i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + durations[i] + 1;
  }
  int binarySearch(int val) {
    int low = 0;
    int high = n;
    while (low < high) {
      int mid = low + (high - low) ~/ 2;
      if (prefix[mid] < val) {
        low = mid + 1;
      } else {
        high = mid;
      }
    }
    return low;
  }
  int k = binarySearch(targetMinutes);
  if (k == n) return [];
  return [k - 1];
}

