    for (var role in roles.keys) role: {
      for (var resource in resources.keys) resource: 0,
    },
  };

  void grantAccess(String role, String resource, int permission) {
    accessMatrix[role]![resource] = (accessMatrix[role]![resource] ?? 0) | permission;
  }

  void denyAccess(String role, String resource, int permission) {
    accessMatrix[role]![resource] = (accessMatrix[role]![resource] ?? 0) & ~permission;
  }

  bool checkAccess(String role, String resource, int permission) {
    return (accessMatrix[role]![resource] ?? 0) & permission != 0;
  }

  void listPermissions(String role) {
    print('Role: $role');
    print('Permissions:');
    for (var resource in resources.keys) {
      print('  ${resource.padRight(15)}: ${checkAccess(role, resource, 0x1000)}');
