    print('Permissions:');
    for (var role in users.keys) {
      if (users[role]?.contains(user) ?? false) {
        print('  ${role.padRight(15)}: ${checkAccess(role, "*", 0x1000)}');
      }
    }
    print('');
  }

  void listResourcesForRole(String role) {
