        centroids[c] = newCentroid;
        continue;
      }

      newCentroid[0] = totalX / pointCount;
      newCentroid[1] = totalY / pointCount;

      double oldDist = double.infinity;
      double minDist = double.infinity;

      for (int idx in pointsInCluster) {
        double dist = distance(newCentroid, points[idx]);
        if (dist < oldDist) {
          oldDist = dist;
          minDist = idx;
        }
      }

      assignments[minDist] = c;

      if (oldDist == double.infinity) {

        bool revisable = false;
        for (int idx in pointsInCluster) {
          if (assignments[idx] == -1) {
            revisable = true;
            break;
          }
