          }
        }
        if (revisable) {

          bool movesNearby = false;
          for (int idx in pointsInCluster) {
            if (assignments[idx] != -1 &&
                (points[idx][0] - newCentroid[0]).abs() +
                (points[idx][1] - newCentroid[1]).abs() < tolerance) {
              movesNearby = true;
              break;
            }
          }
          if (!movesNearby) {
