      }

      if (oldDist > tolerance) {

        bool revisable = false;
        for (int idx in pointsInCluster) {
          if (assignments[idx] != -1 &&
              (points[idx][0] - newCentroid[0]).abs() +
              (points[idx][1] - newCentroid[1]).abs() < tolerance) {
            revisable = true;
            break;
          }
        }
        if (revisable) {

          bool movesNearby = false;
          for (int idx in pointsInCluster) {
            if (assignments[idx] != -1 &&
                (points[idx][0] - newCentroid[0]).abs() +
                (points[idx][1] - newCentroid[1]).abs() < tolerance) {
              movesNearby = true;
              break;
            }
          }
          if (movesNearby) {
            assignments[c] = -1;
          }
        }
      }
    }

    for (int c = 0; c < k; c++) {
      if (assignments[c] != -1) {
        List<int> neighbors = [];
        for (int idx in pointsInCluster(c)) {
          int assigned = assignments[idx];
          if (assigned == (c == 0 ? 1 : 0)) continue; 
          neighbors.add(assigned);
        }

        double newDist = double.infinity;
        bool revisable = false;

        for (int neighbor in neighbors) {
          if (neighbor == -1) continue;

          List<double> nc = List.from(centroids[neighbor]);
          double d = distance(nc, centroids[c]);
          if (d < newDist) {
            newDist = d;
            revisable = true;
          }
        }

