      converged = true;
      print('Converged in $iterations iteration(s).');
    } else {
      print('  Points: ${points.map((p) => '${p[0]},${p[1]}').join(' ')}');
      print('  centroid: ${centroids.map((p) => '${p[0]},${p[1]}').join(' ')}');
