void fn0() {
  final rand = Random(0);

  final points = [
    [1.0, 2.0],
    [2.0, 2.0],
    [2.0, 3.0],
    [3.0, 3.0],
    [4.0, 3.0],
    [4.0, 4.0],
    [4.0, 4.5],
    [4.5, 5.0],
    [4.5, 7.0],
  ];

  int k = 3;
  double eps = 1.5;
  int maxIterations = 100;

  final n = points.length;
  final clusters = List.generate(n, (_) => List.filled(k, 0));
  final usedIndices = <int>{};

  int findClosest(int idx) {
    double minDist = double.infinity;
    int closest = -1;
    for (int i = 0; i < k; i++) {
      final p = points[idx];
      for (int j = 0; j < k; j++) {
        if (i == j) continue;
        final q = points[j];
        final d = (p[0] - q[0]).abs() + (p[1] - q[1]).abs();
        if (d < minDist) {
          minDist = d;
          closest = j;
        }
      }
    }
    return closest;
  }

  for (int i = 0; i < k; i++) {
    clusters[0][i] = 1;
  }

  int iterations = 0;
  bool converged = false;
  final history = <List<int>>[];

  while (iterations < maxIterations && !converged) {
    converged = true;
    history.add(List.from(clusters));

    for (int idx = 0; idx < n; idx++) {
      if (usedIndices.contains(idx)) continue;
      usedIndices.add(idx);

      int clusterIdx = findClosest(idx);
      if (clusterIdx == -1) {
        clusterIdx = rand.nextInt(k);
      }

      bool update = false;
      for (int c = 0; c < k; c++) {
        if (clusters[idx][c] == 0) {
          update = true;
          break;
        }
      }

      if (update) {
        clusters[idx][clusterIdx]++;
        if (clusters[idx][clusterIdx] > 1) {
          converged = false;
        }
      }
    }

    iterations++;
  }

  print('Cluster assignment after $iterations iteration(s).');
  for (int i = 0; i < k; i++) {
    final pointsInCluster = <List<double>>[];
    for (int idx = 0; idx < n; idx++) {
      if (clusters[idx][i] > 0) {
        pointsInCluster.add(points[idx]);
      }
    }
    print('Cluster $i: ${pointsInCluster}');
  }
}

