        for (int j = 0; j < sub.length; j++) {
          cand[sub[j]] = (cand[sub[j]] ?? 0) + 1;
        }
        bool tied = false;
        int maxCount = 0;
        for (var v in cand.values) {
          if (v > 0 && v < maxCount) {
            tied = true;
          }
          if (v > maxCount) {
            maxCount = v;
          }
        }
        if (tied) {
          continue;
        }
        return cand;
      }
    }
    return {};
  }
  int windowSize = maxCandidates;
  List<List<String>> windows = [];
  for (int i = 0; i < votes.length; i++) {
    if (i >= windowSize) {
      windows.add(votes.sublist(i - windowSize, i));
    }
  }
  Map<String, int> best = {};
  int bestCount = 0;
  for (List<String> w in windows) {
    Map<String, int> cand = {};
    for (int j = 0; j < w.length; j++) {
      cand[w[j]] = (cand[w[j]] ?? 0) + 1;
    }
    bool tied = false;
    int count = 0;
    for (var v in cand.values) {
      if (v > 0 && v < count) {
        tied = true;
      }
      if (v > count) {
        count = v;
      }
    }
    if (tied) {
      continue;
    }
    if (count > bestCount) {
      best = cand;
      bestCount = count;
    }
  }
  return best;
}

